changeSet.sql:
CREATE INDEX IF NOT EXISTS idx_pg_mpi_family_trgm
    ON hc_patients USING GIN (family_name gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_pg_mpi_given_trgm
    ON hc_patients USING GIN (given_name gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_pg_code_display_en_trgm
    ON hc_code_systems USING GIN (display_en gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_pg_code_display_fr_trgm
    ON hc_code_systems USING GIN (display_fr gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_pg_outbox_pending_queue
    ON hc_outbox_events (next_attempt_at, created_at)
    WHERE status IN ('PENDING', 'FAILED');

CREATE INDEX IF NOT EXISTS idx_pg_ward_beds_available
    ON hc_ward_beds (facility_id, ward_code)
    WHERE occupied = FALSE;

CREATE INDEX IF NOT EXISTS idx_pg_clinical_orders_open
    ON hc_clinical_orders (facility_id, ordered_at)
    WHERE status = 'ORDERED';

CREATE INDEX IF NOT EXISTS idx_pg_pharmacy_fefo_stock
    ON hc_medication_batches (facility_id, drug_code, expiry_date ASC)
    WHERE quarantined = FALSE AND quantity_on_hand > 0;

CREATE INDEX IF NOT EXISTS idx_pg_lab_unack_panic
    ON hc_diagnostic_reports (facility_id, verified_at)
    WHERE panic_acknowledged_by IS NULL;

CREATE INDEX IF NOT EXISTS idx_pg_sync_conflicts_unresolved
    ON hc_sync_conflicts (facility_id, created_at)
    WHERE resolved_by IS NULL;
